@js:
eval(String(source.sourceComment));
url = api + "?ac=detail&pg={{page}}";

// 搜索（变量关键词），改完要刷新分类
function surl(){
	key = source.getVariable();
	if(key==""||key==null){ source.setVariable('伍六七'); }
	key = source.getVariable();
	return "变量搜索::" + url + "&wd=" + key + "\n";
}

// 分类：父类（电影片/连续剧/综艺片/动漫片/体育）只是分组，条目都挂在子类里，
// 直接按父类取会只剩 0~3 条（综艺片在量子接口上 total=1，所以“综艺只有一条”）
cacheKey = api + "#v2";
sort = cache.get(cacheKey);
if(sort==null){
	x = 0;
	function build(){
		try{
			d = JSON.parse(java.ajax(api + "?ac=list&pg=1"));
			cls = d.class || [];
			list = [];
			for(var i=0;i<cls.length;i++){
				var c = cls[i], child = false;
				for(var j=0;j<cls.length;j++){
					if(cls[j].type_pid == c.type_id){ child = true; break; }
				}
				if(child) continue;                       // 跳过纯分组的父类
				list.push({id:c.type_id, name:c.type_name, u:url+"&t="+c.type_id});
			}
			var urls = [];
			for(var k=0;k<list.length;k++){ urls.push(api+"?ac=list&pg=1&t="+list[k].id); }
			var res = java.ajaxAll(urls), out = [];
			for(var m=0;m<list.length;m++){
				var ok = false;
				try{
					var dd = JSON.parse(res[m].body());
					ok = dd.list && dd.list.length>0 && dd.list[0].vod_name;
				}catch(e){ ok = false; }
				if(ok) out.push(list[m].name + "::" + list[m].u);
			}
			if(out.length>0){
				var str = out.join("\n");
				cache.put(cacheKey, str);
				return str;
			}
			return "";
		}catch(e){ return ""; }
	}
	sort = build();
}
"最近更新::" + url + "\n" + surl() + sort

